using System;public class Solution{class R{public bool ok;public int n,lo,hi;public R(bool o,int n,int l,int h){ok=o;this.n=n;lo=l;hi=h;}}int b;R F(TreeNode x){if(x==null)return new R(true,0,int.MaxValue,int.MinValue);var l=F(x.left);var r=F(x.right);if(l.ok&&r.ok&&x.val>l.hi&&x.val<r.lo){var z=new R(true,l.n+r.n+1,l.n>0?l.lo:x.val,r.n>0?r.hi:x.val);b=Math.Max(b,z.n);return z;}return new R(false,0,0,0);}public int LargestBSTSubtree(TreeNode r){F(r);return b;}}
